/*!
 * RoofGlow — roofline measuring and Christmas light preview
 * Long Island Christmas Lights Pros
 * Plain JavaScript, no frameworks. Everything is scoped to the #roofglow element.
 */
(function(){
  'use strict';
  function boot(){
  const root = document.getElementById('roofglow');
  if (!root || root.dataset.rgReady) return;      // no embed on this page, or already started
  root.dataset.rgReady = '1';

  // '#name' looks up the prefixed element id 'rg-name' inside RoofGlow
  const $ = s => (s[0] === '#' && /^#[\w-]+$/.test(s)) ? document.getElementById('rg-' + s.slice(1)) : root.querySelector(s);
  const COLORS = ['#F2B544','#5AA9FF','#47D18A','#FF7AD9','#FF8A4C','#B48CFF','#4FD6D6'];
  const LOOKS = {
    warm:  ['#FFD27A'],
    pure:  ['#EEF6FF'],
    candy: ['#FF3B3B','#F4F8FF'],
    multi: ['#FF5A5A','#47D18A','#5AA9FF','#FFC23D','#FF7AD9']
  };
  const coarse = matchMedia('(pointer: coarse)').matches;

  const S = {
    img:null, mode:'scale', scalePts:[], pxPerFt:null,
    strings:[{id:1,name:'First floor',color:COLORS[0]}], active:1, nextId:2,
    runs:[], current:[], hover:null, manual:[], photoCount:0
  };
  const cv = $('#cv'), ctx = cv.getContext('2d'), stage = $('#stage'), empty = $('#empty');
  let view = {k:1,w:0,h:0};

  const dist = (a,b) => Math.hypot(a.x-b.x, a.y-b.y);
  const polyPx = pts => pts.reduce((s,p,i)=> i ? s + dist(pts[i-1],p) : 0, 0);
  // Sloped edges (like gable rakes) measure short in a photo, so they get extra length.
  // Level and plumb lines (within 10 degrees) are left as measured.
  function segMult(a, b){
    const ang = Math.atan2(Math.abs(b.y - a.y), Math.abs(b.x - a.x)) * 180 / Math.PI;
    return (ang > 10 && ang < 80) ? 1 + (parseFloat(document.getElementById('rg-angleAdj').value) || 0) / 100 : 1;
  }
  const segFt = (a, b) => S.pxPerFt ? dist(a, b) * segMult(a, b) / S.pxPerFt : null;
  const polyFt = pts => pts.reduce((s,p,i)=> i ? s + segFt(pts[i-1], p) : 0, 0);
  const toFt = px => S.pxPerFt ? px / S.pxPerFt : null;
  const strOf = id => S.strings.find(s => s.id === id) || S.strings[0];
  const num = id => parseFloat($(id).value) || 0;
  const esc = t => t.replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  function fmt(ft){
    if (ft == null || isNaN(ft)) return 'n/a';
    let f = Math.floor(ft), i = Math.round((ft - f) * 12);
    if (i === 12){ f++; i = 0; }
    return i ? `${f} ft ${i} in` : `${f} ft`;
  }

  /* ---------- Loading photos ---------- */
  function loadFile(file){
    if (!file || !file.type.startsWith('image/')) { hint('That file isn\'t an image. Choose a JPG, PNG, or HEIC photo.'); return; }
    const r = new FileReader();
    r.onload = () => {
      const img = new Image();
      img.onload = () => {
        S.img = img; S.scalePts = []; S.pxPerFt = null; S.runs = []; S.current = [];
        empty.hidden = true; cv.hidden = false;
        setMode('scale'); fit(); update();
      };
      img.src = r.result;
    };
    r.readAsDataURL(file);
  }
  $('#file').addEventListener('change', e => { loadFile(e.target.files[0]); e.target.value=''; });
  ['dragenter','dragover'].forEach(t => stage.addEventListener(t, e => { e.preventDefault(); empty.classList.add('rg-drag'); }));
  ['dragleave','drop'].forEach(t => stage.addEventListener(t, e => { e.preventDefault(); empty.classList.remove('rg-drag'); }));
  stage.addEventListener('drop', e => loadFile(e.dataTransfer.files[0]));

  /* ---------- Canvas sizing & drawing ---------- */
  function fit(){
    if (!S.img) return;
    const maxW = stage.clientWidth, maxH = Math.max(320, window.innerHeight * 0.72);
    const k = Math.min(maxW / S.img.naturalWidth, maxH / S.img.naturalHeight);
    const w = S.img.naturalWidth * k, h = S.img.naturalHeight * k, dpr = window.devicePixelRatio || 1;
    cv.width = Math.round(w*dpr); cv.height = Math.round(h*dpr);
    cv.style.width = w+'px'; cv.style.height = h+'px';
    ctx.setTransform(dpr,0,0,dpr,0,0);
    view = {k,w,h};
    draw();
  }
  new ResizeObserver(fit).observe(stage);

  const sc = p => ({x:p.x*view.k, y:p.y*view.k});

  function label(text, x, y, color){
    ctx.font = '700 12px "Atkinson Hyperlegible", system-ui, sans-serif';
    const w = ctx.measureText(text).width + 12;
    ctx.fillStyle = 'rgba(13,21,32,.85)';
    ctx.beginPath(); ctx.roundRect(x - w/2, y - 22, w, 18, 9); ctx.fill();
    ctx.fillStyle = color; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(text, x, y - 13);
  }

  function bulb(x, y, color){
    const g = ctx.createRadialGradient(x, y, 0, x, y, 9);
    g.addColorStop(0, color + 'CC'); g.addColorStop(1, color + '00');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y, 9, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = color; ctx.beginPath(); ctx.arc(x, y, 3.2, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.85)'; ctx.beginPath(); ctx.arc(x-1, y-1, 1.1, 0, Math.PI*2); ctx.fill();
  }

  function along(pts, step){
    const out = []; let carry = 0;
    for (let i=1;i<pts.length;i++){
      const a = pts[i-1], b = pts[i], L = dist(a,b) * segMult(a,b);   // angled runs fit more bulbs
      let t = carry;
      while (t <= L){ const f = L ? t/L : 0; out.push({x:a.x+(b.x-a.x)*f, y:a.y+(b.y-a.y)*f}); t += step; }
      carry = t - L;
    }
    return out;
  }

  function drawRun(pts, strColor, active){
    const s = pts.map(sc);
    // wire in the string's color so each string is easy to tell apart
    ctx.strokeStyle = strColor; ctx.globalAlpha = active ? 1 : .8;
    ctx.lineWidth = 3; ctx.lineJoin = 'round';
    ctx.beginPath(); s.forEach((p,i)=> i ? ctx.lineTo(p.x,p.y) : ctx.moveTo(p.x,p.y)); ctx.stroke();
    ctx.globalAlpha = 1;

    let step = 14;
    if (S.pxPerFt){ step = (num('#spacing')/12) * S.pxPerFt * view.k; while (step < 8) step *= 2; }
    const pal = LOOKS[$('#look').value] || LOOKS.warm;
    along(s, step).forEach((p, n) => bulb(p.x, p.y, pal[n % pal.length]));
    if (S.pxPerFt){
      for (let i=1;i<pts.length;i++){
        const m = sc({x:(pts[i-1].x+pts[i].x)/2, y:(pts[i-1].y+pts[i].y)/2});
        label(fmt(segFt(pts[i-1],pts[i])), m.x, m.y, '#FFE6B0');
      }
    }
    s.forEach((p,i) => {
      ctx.fillStyle = strColor; ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.arc(p.x,p.y, i===0 || i===s.length-1 ? 5 : 4, 0, Math.PI*2); ctx.fill(); ctx.stroke();
    });
  }

  function hoverPoint(){
    if (!S.hover) return null;
    return S.hover;
  }

  function draw(){
    if (!S.img) return;
    ctx.clearRect(0,0,view.w,view.h);
    ctx.drawImage(S.img,0,0,view.w,view.h);
    ctx.fillStyle='rgba(8,16,28,.22)'; ctx.fillRect(0,0,view.w,view.h);

    if (S.scalePts.length){
      const pts = S.scalePts.map(sc);
      ctx.strokeStyle='#FF6B7A'; ctx.lineWidth=2.5; ctx.setLineDash([7,5]);
      ctx.beginPath(); ctx.moveTo(pts[0].x,pts[0].y);
      const end = pts[1] || (S.mode==='scale' && S.hover ? sc(S.hover) : null);
      if (end) ctx.lineTo(end.x,end.y);
      ctx.stroke(); ctx.setLineDash([]);
      pts.forEach(p => { ctx.fillStyle='#FF6B7A'; ctx.beginPath(); ctx.arc(p.x,p.y,5,0,Math.PI*2); ctx.fill(); });
      if (S.pxPerFt && pts[1]) label('Scale: ' + fmt(toFt(dist(S.scalePts[0],S.scalePts[1]))), (pts[0].x+pts[1].x)/2, (pts[0].y+pts[1].y)/2, '#FFC3CA');
    }

    S.runs.forEach(r => drawRun(r.pts, strOf(r.sid).color, false));
    if (S.current.length){
      const color = strOf(S.active).color;
      drawRun(S.current, color, true);
      const hp = hoverPoint();
      if (S.mode==='trace' && hp){
        const a = sc(S.current[S.current.length-1]), b = sc(hp);
        ctx.strokeStyle = color; ctx.lineWidth = 2; ctx.setLineDash([5,5]);
        ctx.beginPath(); ctx.moveTo(a.x,a.y); ctx.lineTo(b.x,b.y); ctx.stroke(); ctx.setLineDash([]);
        if (S.pxPerFt) label(fmt(segFt(S.current[S.current.length-1], hp)), b.x, b.y - 6, '#FFD27A');
      }
    }
  }

  /* ---------- Interaction ---------- */
  function toImg(e){
    const r = cv.getBoundingClientRect();
    return {x:(e.clientX - r.left)/view.k, y:(e.clientY - r.top)/view.k};
  }
  cv.addEventListener('pointerdown', e => {
    if (!S.img || e.button !== 0) return;
    if (document.activeElement !== cv) cv.focus({preventScroll:true});
    const p = toImg(e);

    if (S.mode === 'scale'){
      if (S.scalePts.length >= 2){ S.scalePts = []; S.pxPerFt = null; }
      S.scalePts.push(p);
      if (S.scalePts.length === 2){ $('#scaleform').classList.add('rg-show'); $('#sFt').focus(); $('#sFt').select(); }
      update(); return;
    }

    const last = S.current[S.current.length-1];
    if (last && dist(last,p)*view.k < 10) finishRun();   // clicking the last point again ends the run
    else S.current.push(p);
    update();
  });
  cv.addEventListener('pointermove', e => { if (S.img){ S.hover = toImg(e); draw(); } });
  cv.addEventListener('pointerleave', () => { S.hover = null; draw(); });

  function setMode(m){
    S.mode = m;
    $('#mScale').setAttribute('aria-pressed', m==='scale');
    $('#mTrace').setAttribute('aria-pressed', m==='trace');
    if (m !== 'scale') $('#scaleform').classList.remove('rg-show');
    update();
  }
  $('#mScale').onclick = () => setMode('scale');
  $('#mTrace').onclick = () => setMode('trace');

  $('#applyScale').onclick = () => {
    const ft = num('#sFt') + num('#sIn')/12;
    if (S.scalePts.length < 2 || ft <= 0){ hint('Enter a length greater than zero for the scale line.'); return; }
    S.pxPerFt = dist(S.scalePts[0], S.scalePts[1]) / ft;
    $('#scaleform').classList.remove('rg-show');
    setMode('trace');
  };

  function finishRun(){
    if (S.current.length >= 2) S.runs.push({sid:S.active, pts:S.current});
    S.current = [];
    update();
  }
  $('#finish').onclick = finishRun;
  function undo(){
    if (S.current.length) S.current.pop();
    else if (S.runs.length){ const r = S.runs.pop(); S.active = r.sid; S.current = r.pts; S.current.pop(); }
    else if (S.scalePts.length){ S.scalePts.pop(); S.pxPerFt = null; setMode('scale'); }
    update();
  }
  $('#undo').onclick = undo;
  $('#clear').onclick = () => { S.runs = []; S.current = []; update(); };

  cv.addEventListener('keydown', e => {
    if (!S.img) return;
    if (e.key === 'Enter'){ e.preventDefault(); finishRun(); }
    else if (e.key === 'Escape'){ S.current = []; update(); }
    else if (e.key === 'Backspace' || ((e.metaKey||e.ctrlKey) && e.key.toLowerCase()==='z')){ e.preventDefault(); undo(); }
  });

  $('#savePhoto').onclick = () => {
    finishRun();
    if (!S.pxPerFt || !S.runs.length) return;
    S.photoCount++;
    S.runs.forEach((r,i) => S.manual.push({name:`Photo ${S.photoCount}, run ${i+1}`, feet: polyFt(r.pts), sid:r.sid}));
    S.img = null; S.runs = []; S.current = []; S.scalePts = []; S.pxPerFt = null;
    cv.hidden = true; empty.hidden = false;
    update();
    hint(`Saved photo ${S.photoCount}. Upload a photo of the next side.`);
  };

  /* ---------- Watermark (logo + phone number) ---------- */
  const BRAND_PHONE = '(516) 780-6151';
  const LOGO = new Image();
  LOGO.onload = () => schedulePreview();
  LOGO.src = 'data:image/png;base64,';

  const SHOW_WATERMARK = false;   // set to true to put the logo and phone number back on the preview
  function drawWatermark(g, W, H){
    if (!SHOW_WATERMARK) return;
    if (!LOGO.complete || !LOGO.naturalWidth) return;
    const short = Math.min(W, H);
    const wmW = Math.min(Math.max(W * 0.24, 200), 560, W * 0.6);
    const logoH = wmW * LOGO.naturalHeight / LOGO.naturalWidth;
    const pad = wmW * 0.07, fs = wmW * 0.088, gap = wmW * 0.03;
    const boxW = wmW + pad * 2, boxH = pad + logoH + gap + fs * 1.15 + pad * 0.8;
    const m = Math.max(12, short * 0.025);
    const x = W - boxW - m, y = H - boxH - m;

    g.save();
    g.globalCompositeOperation = 'source-over'; g.globalAlpha = 1;
    g.shadowColor = 'rgba(0,0,0,.35)'; g.shadowBlur = pad; g.shadowOffsetY = pad * 0.2;
    g.fillStyle = 'rgba(255,255,255,.86)';
    g.beginPath(); g.roundRect(x, y, boxW, boxH, pad * 0.9); g.fill();
    g.shadowColor = 'transparent';
    g.drawImage(LOGO, x + pad, y + pad, wmW, logoH);
    g.fillStyle = '#5E5E5E';
    g.font = `700 ${fs}px "Atkinson Hyperlegible", Arial, sans-serif`;
    g.textAlign = 'center'; g.textBaseline = 'top';
    g.fillText(BRAND_PHONE, x + boxW / 2, y + pad + logoH + gap);
    g.restore();
  }

  /* ---------- Night preview ---------- */
  const pv = $('#pv'), pvC = $('#pvCanvas'), pg = pvC.getContext('2d');
  const rand = n => { const x = Math.sin(n * 12.9898) * 43758.5453; return x - Math.floor(x); };
  const hexArr = h => { const n = parseInt(h.slice(1), 16); return [n>>16&255, n>>8&255, n&255]; };
  // Relative bulb size by type
  function bulbSize(){
    const t = $('#bulbType').selectedOptions[0].textContent;
    return /mini/i.test(t) ? 0.6 : /C7/.test(t) ? 0.85 : 1;
  }
  const P = {ready:false, W:0, H:0, r:1, base:null, baseKey:'', lit:null, bulbs:[], sprites:[],
             flakes:[], flakeSprite:null, running:false, visible:true, last:0};
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) $('#pvMotion').checked = false;

  /* Step 1: turn the daytime photo into a believable night shot.
     Colors are muted, mid-tones pushed down (whites like siding stay readable),
     everything shifts cool blue, and bright sky above the roofline goes deep navy. */
  function nightBase(img, W, H, dark, runs){
    const key = [img.src.length, img.src.slice(-32), W, dark, JSON.stringify(runs.map(p => p.length))].join('|');
    if (P.baseKey === key) return P.base;
    const c = document.createElement('canvas'); c.width = W; c.height = H;
    const x = c.getContext('2d'); x.drawImage(img, 0, 0, W, H);

    // Sky can only be above the traced roofline. Build that limit for each column.
    const limit = new Float32Array(W).fill(-1); const ys = [];
    runs.forEach(pts => { for (let i=1;i<pts.length;i++){
      const a = pts[i-1], b = pts[i], x0 = Math.max(0, Math.round(Math.min(a.x,b.x))), x1 = Math.min(W-1, Math.round(Math.max(a.x,b.x)));
      for (let xx=x0; xx<=x1; xx++){ const f = b.x===a.x ? 0 : (xx-a.x)/(b.x-a.x); const y = a.y + (b.y-a.y)*f; if (y > limit[xx]) limit[xx] = y; }
      ys.push(a.y, b.y);
    }});
    // Beside the house, sky can reach a little below the lowest roof edge (behind trees, etc.)
    const fallback = ys.length ? Math.min(H, Math.max(...ys) + H * 0.12) : H * 0.4;
    for (let xx=0; xx<W; xx++) if (limit[xx] < 0) limit[xx] = fallback;
    const fade = H * 0.04;

    const d = x.getImageData(0, 0, W, H), a = d.data;
    const desat = 0.6*dark, gam = 1 + 0.9*dark, gain = 1 - 0.48*dark;
    const tr = 1 - 0.30*dark, tg = 1 - 0.17*dark, tb = 1 + 0.12*dark;
    const NR = 0.03, NG = 0.05, NB = 0.13;
    for (let yy=0; yy<H; yy++){
      for (let xx=0; xx<W; xx++){
        const i = (yy*W + xx) * 4;
        let r = a[i]/255, g = a[i+1]/255, b = a[i+2]/255;
        const lum = 0.299*r + 0.587*g + 0.114*b;
        const above = Math.min(1, Math.max(0, (limit[xx] - yy) / fade));
        const sky = above * Math.min(1, Math.max(0, (lum - 0.45) / 0.3)) * (b >= r*0.9 ? 1 : 0.5);
        r += (lum - r)*desat; g += (lum - g)*desat; b += (lum - b)*desat;
        r = Math.pow(r, gam)*gain*tr; g = Math.pow(g, gam)*gain*tg; b = Math.pow(b, gam)*gain*tb;
        const k = sky * 0.92 * dark;
        a[i] = (r + (NR - r)*k) * 255; a[i+1] = (g + (NG - g)*k) * 255; a[i+2] = (b + (NB - b)*k) * 255;
      }
    }
    x.putImageData(d, 0, 0);
    P.base = c; P.baseKey = key;
    return c;
  }

  /* Step 2: soft light falling on the fascia and siding right under the lights. */
  function buildLit(img, base, runs, bulbs, step, glow, pal){
    const {W, H} = P;
    const c = document.createElement('canvas'); c.width = W; c.height = H;
    const x = c.getContext('2d'); x.drawImage(base, 0, 0);
    const L = document.createElement('canvas'); L.width = W; L.height = H;
    const l = L.getContext('2d'); l.fillStyle = '#000'; l.fillRect(0, 0, W, H);
    l.globalCompositeOperation = 'lighter';
    const sR = Math.max(step * 1.6, H * 0.025);
    const aSpill = Math.min(0.5, 0.6 * glow * step / (1.6 * sR));   // keep overlapping bulbs from blowing out
    bulbs.forEach(b => {
      const [cr, cg, cb] = pal[b.ci];
      l.save(); l.translate(b.x, b.y + sR * 0.55); l.scale(1.6, 1);
      const gr = l.createRadialGradient(0, 0, 0, 0, 0, sR);
      gr.addColorStop(0, `rgba(${cr},${cg},${cb},${aSpill})`);
      gr.addColorStop(1, `rgba(${cr},${cg},${cb},0)`);
      l.fillStyle = gr; l.fillRect(-sR, -sR, sR*2, sR*2); l.restore();
    });
    const T = document.createElement('canvas'); T.width = W; T.height = H;
    const t = T.getContext('2d'); t.drawImage(img, 0, 0, W, H);
    t.globalCompositeOperation = 'multiply'; t.drawImage(L, 0, 0);
    x.globalCompositeOperation = 'lighter'; x.drawImage(T, 0, 0);
    // the wire, barely visible
    x.globalCompositeOperation = 'source-over';
    x.strokeStyle = 'rgba(10,16,12,.6)'; x.lineWidth = Math.max(1, step * 0.04); x.lineJoin = 'round';
    runs.forEach(pts => { x.beginPath(); pts.forEach((p,i) => i ? x.lineTo(p.x,p.y) : x.moveTo(p.x,p.y)); x.stroke(); });
    return c;
  }

  /* Step 3: one pre-drawn bulb image per color, so hundreds of bulbs can animate smoothly. */
  function makeSprite([r, g, b], cr, glow){
    const hR = cr * 5.5, size = Math.ceil(hR * 2) + 2, m = size / 2;
    const c = document.createElement('canvas'); c.width = c.height = size;
    const x = c.getContext('2d');
    const h = x.createRadialGradient(m, m, 0, m, m, hR);
    h.addColorStop(0,   `rgba(${r},${g},${b},${0.25 + 0.5 * glow})`);
    h.addColorStop(0.2, `rgba(${r},${g},${b},${0.08 + 0.3 * glow})`);
    h.addColorStop(0.5, `rgba(${r},${g},${b},${0.05 * glow + 0.02})`);
    h.addColorStop(1,   `rgba(${r},${g},${b},0)`);
    x.fillStyle = h; x.fillRect(0, 0, size, size);
    const k = x.createRadialGradient(m, m - cr * 0.25, 0, m, m, cr);
    k.addColorStop(0, 'rgba(255,253,245,1)');
    k.addColorStop(0.5, `rgba(${Math.min(255, r + 40)},${Math.min(255, g + 40)},${Math.min(255, b + 40)},1)`);
    k.addColorStop(1, `rgba(${r},${g},${b},.9)`);
    x.fillStyle = k; x.beginPath(); x.ellipse(m, m, cr * 0.8, cr, 0, 0, Math.PI * 2); x.fill();
    return {c, m};
  }
  function makeFlakeSprite(){
    const c = document.createElement('canvas'); c.width = c.height = 32;
    const x = c.getContext('2d'), g = x.createRadialGradient(16, 16, 0, 16, 16, 16);
    g.addColorStop(0, 'rgba(255,255,255,1)'); g.addColorStop(0.4, 'rgba(255,255,255,.75)'); g.addColorStop(1, 'rgba(255,255,255,0)');
    x.fillStyle = g; x.fillRect(0, 0, 32, 32);
    return c;
  }
  P.flakeSprite = makeFlakeSprite();

  function makeFlakes(){
    const {W, H} = P, s = W / 1400;
    const n = Math.min(1600, Math.round(num('#pvSnow') / 100 * W * H / 2200));
    while (P.flakes.length > n) P.flakes.pop();
    while (P.flakes.length < n){
      const z = Math.random();               // depth: 0 = far, 1 = near
      P.flakes.push({x: Math.random() * W, y: Math.random() * H, z,
        r: (0.7 + z * z * 3.2) * s, vy: (18 + z * 75) * s, sway: (6 + z * 18) * s,
        ph: Math.random() * 6.283, a: 0.35 + z * 0.6});
    }
  }

  /* Rebuild everything that depends on the photo, tracing or settings */
  function renderPreview(){
    const ready = !!S.img && (S.runs.length > 0 || S.current.length >= 2);
    $('#pvFrame').hidden = !ready; $('#pvEmpty').hidden = ready;
    P.ready = ready;
    if (!ready) return;
    if ($('#pvBefore').src !== S.img.src) $('#pvBefore').src = S.img.src;
    $('#pvLook').value = $('#look').value;
    setSplit();

    const img = S.img, iw = img.naturalWidth, ih = img.naturalHeight;
    const r = Math.min(1, 1800 / Math.max(iw, ih)), W = Math.round(iw*r), H = Math.round(ih*r);
    const resized = W !== P.W || H !== P.H;
    P.W = W; P.H = H; P.r = r;
    if (resized){ pvC.width = W; pvC.height = H; P.flakes = []; }
    const dark = num('#pvDark')/100, glow = num('#pvGlow')/100;
    const pal = (LOOKS[$('#look').value] || LOOKS.warm).map(hexArr);

    const ppf = S.pxPerFt ? S.pxPerFt * r : null;
    const step = Math.max(4, ppf ? (num('#spacing')/12) * ppf : W * 0.014);
    let cr = Math.min(Math.max(step * 0.15, W * 0.0022), step * 0.42) * bulbSize();
    cr = Math.max(cr, 1.4);
    const runs = [...S.runs.map(x => x.pts), ...(S.current.length >= 2 ? [S.current] : [])]
      .map(pts => pts.map(p => ({x:p.x*r, y:p.y*r})));
    const bulbs = []; let seed = 0, idx = 0;
    runs.forEach(pts => along(pts, step).forEach((p, i) => {
      seed++;
      bulbs.push({x:p.x, y:p.y, ci:i % pal.length, idx: idx++,
                  ph: rand(seed) * 6.283, sp: 0.6 + rand(seed + 999) * 0.9, k: 0.88 + rand(seed + 77) * 0.2});
    }));
    P.bulbs = bulbs;
    P.sprites = pal.map(c => makeSprite(c, cr, glow));
    const base = nightBase(img, W, H, dark, runs);
    P.lit = buildLit(img, base, runs, bulbs, step, glow, pal);
    makeFlakes();
    kick();
  }

  /* How bright each bulb is right now, for the chosen light effect */
  function level(b, t, mode){
    switch (mode){
      case 'twinkle': return b.k * (0.8 + 0.2 * Math.sin(t * b.sp * 2.2 + b.ph));
      case 'sparkle': { const s = Math.sin(t * b.sp * 1.6 + b.ph); return b.k * (0.82 + (s > 0.9 ? (s - 0.9) * 6 : 0)); }
      case 'chase':   return 0.3 + 0.75 * (0.5 + 0.5 * Math.sin(t * 4 - b.idx * 0.5));
      default:        return b.k;
    }
  }

  function frame(now, move){
    if (!P.ready || !P.lit) return;
    const t = now / 1000, dt = Math.min(0.05, Math.max(0, t - P.last)); P.last = t;
    const {W, H} = P, mode = $('#pvFx').value;
    pg.globalCompositeOperation = 'source-over'; pg.globalAlpha = 1;
    pg.drawImage(P.lit, 0, 0);
    pg.globalCompositeOperation = 'lighter';
    for (const b of P.bulbs){
      const s = P.sprites[b.ci], v = level(b, t, mode);
      pg.globalAlpha = Math.min(1, v); pg.drawImage(s.c, b.x - s.m, b.y - s.m);
      if (v > 1){ pg.globalAlpha = Math.min(1, v - 1); pg.drawImage(s.c, b.x - s.m, b.y - s.m); }
    }
    pg.globalCompositeOperation = 'source-over';
    for (const f of P.flakes){
      if (move){
        f.y += f.vy * dt; f.x += Math.sin(t * 0.9 + f.ph) * f.sway * dt;
        if (f.y > H + 6){ f.y = -6; f.x = Math.random() * W; }
        if (f.x < -6) f.x = W + 6; else if (f.x > W + 6) f.x = -6;
      }
      const d = f.r * 3.2;
      pg.globalAlpha = f.a; pg.drawImage(P.flakeSprite, f.x - d/2, f.y - d/2, d, d);
    }
    pg.globalAlpha = 1;
    drawWatermark(pg, W, H);
  }

  const animating = () => P.ready && P.visible && $('#pvMotion').checked && (num('#pvSnow') > 0 || $('#pvFx').value !== 'steady');
  function tick(now){
    if (!animating()){ P.running = false; return; }
    frame(now, true);
    requestAnimationFrame(tick);
  }
  function kick(){
    if (animating()){
      if (!P.running){ P.running = true; P.last = performance.now() / 1000; requestAnimationFrame(tick); }
    } else frame(performance.now(), false);
  }
  new IntersectionObserver(es => { P.visible = es[0].isIntersecting; kick(); }).observe(pv);

  let pvQueued = false;
  function schedulePreview(){
    if (pvQueued) return;
    pvQueued = true;
    requestAnimationFrame(() => { pvQueued = false; renderPreview(); });
  }
  function setSplit(){
    const v = num('#pvSplit');
    $('#pvBefore').style.clipPath = `inset(0 ${100 - v}% 0 0)`;
    const d = $('#pvDiv'); d.hidden = v <= 0 || v >= 100; d.style.left = `calc(${v}% - 1px)`;
  }
  $('#preview').onclick = () => pv.scrollIntoView({behavior:'smooth', block:'start'});
  $('#pvSplit').addEventListener('input', setSplit);
  ['#pvDark','#pvGlow'].forEach(id => $(id).addEventListener('input', schedulePreview));
  $('#pvSnow').addEventListener('input', () => { makeFlakes(); kick(); });
  ['#pvFx','#pvMotion'].forEach(id => $(id).addEventListener('change', kick));
  $('#pvLook').addEventListener('change', e => { $('#look').value = e.target.value; update(); });
  $('#pvDownload').onclick = () => {
    pvC.toBlob(blob => {
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob); a.download = 'christmas-lights-preview.jpg';
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(a.href), 2000);
    }, 'image/jpeg', 0.92);
  };

  /* ---------- Start over ---------- */
  $('#reset').onclick = () => {
    if (!confirm('Start over? This removes the photo, scale, all strings, and every run. Your light settings stay the same.')) return;
    Object.assign(S, {
      img:null, mode:'scale', scalePts:[], pxPerFt:null,
      strings:[{id:1,name:'First floor',color:COLORS[0]}], active:1, nextId:2,
      runs:[], current:[], hover:null, manual:[], photoCount:0
    });
    cv.hidden = true; empty.hidden = false;
    $('#scaleform').classList.remove('rg-show');
    $('#mName').value = ''; $('#mFeet').value = '';
    $('#mScale').setAttribute('aria-pressed', false);
    $('#mTrace').setAttribute('aria-pressed', false);
    hint('');
    update();
    root.scrollIntoView({behavior:'smooth', block:'start'});
  };

  /* ---------- Strings ---------- */
  function selectString(id){
    if (id === S.active) return;
    finishRun();            // a run can't switch strings halfway through
    S.active = id; update();
  }
  $('#addString').onclick = () => {
    const n = S.strings.length + 1;
    const names = {2:'Second floor', 3:'Garage', 4:'Porch'};
    const s = {id:S.nextId++, name:names[n] || `String ${n}`, color:COLORS[(n-1) % COLORS.length]};
    S.strings.push(s);
    selectString(s.id);
    if (S.img && S.pxPerFt) setMode('trace');
  };
  function removeString(id){
    const used = S.runs.some(r=>r.sid===id) || S.manual.some(m=>m.sid===id);
    if (used && !confirm(`Remove "${strOf(id).name}" and all of its runs?`)) return;
    S.runs = S.runs.filter(r => r.sid !== id);
    S.manual = S.manual.filter(m => m.sid !== id);
    S.strings = S.strings.filter(s => s.id !== id);
    if (S.active === id){ S.current = []; S.active = S.strings[0].id; }
    update();
  }

  /* ---------- Manual runs ---------- */
  $('#mAdd').onclick = () => {
    const feet = num('#mFeet');
    if (feet <= 0){ $('#mFeet').focus(); return; }
    S.manual.push({name: $('#mName').value.trim() || 'Measured run', feet, sid:S.active});
    $('#mName').value = ''; $('#mFeet').value = '';
    update();
  };
  $('#mFeet').addEventListener('keydown', e => { if (e.key==='Enter') $('#mAdd').click(); });

  /* ---------- Settings ---------- */
  $('#bulbType').onchange = e => { if (e.target.value !== 'custom') $('#watts').value = e.target.value; update(); };
  $('#watts').oninput = () => { $('#bulbType').value = 'custom'; update(); };
  ['#spacing','#pack','#clipSp','#waste','#amps','#look','#angleAdj'].forEach(id => $(id).addEventListener('input', update));

  /* ---------- Math ---------- */
  function itemsFor(sid){
    const items = [];
    S.runs.forEach((r,i) => { if (r.sid===sid) items.push({kind:'photo', idx:i, label:'Traced run', feet: S.pxPerFt ? polyFt(r.pts) : null}); });
    if (sid === S.active && S.current.length >= 2) items.push({kind:'live', label:'Tracing now', feet: S.pxPerFt ? polyFt(S.current) : null});
    S.manual.forEach((m,i) => { if (m.sid===sid) items.push({kind:'manual', idx:i, label:m.name, feet:m.feet}); });
    return items;
  }
  function totals(){
    const waste = 1 + num('#waste')/100, sp = num('#spacing'), pack = Math.max(1, num('#pack')),
          clipSp = Math.max(1, num('#clipSp')), wpb = num('#watts'), cap = num('#amps') * 120 * 0.8;
    const per = S.strings.map(s => {
      const feet = itemsFor(s.id).reduce((a,it)=> a + (it.feet || 0), 0);
      const buy = feet * waste;
      const bulbs = feet ? Math.ceil(buy * 12 / sp) : 0;
      const watts = bulbs * wpb;
      return {s, feet, buy, bulbs,
              packs: feet ? Math.ceil(buy / pack) : 0,   // strands can't be shared between strings
              clips: feet ? Math.ceil(feet * 12 / clipSp) : 0,
              watts, circuits: watts ? Math.ceil(watts / cap) : 0};
    });
    const sum = k => per.reduce((a,p)=> a + p[k], 0);
    const watts = sum('watts');
    return {per, cap, total:sum('feet'), buy:sum('buy'), bulbs:sum('bulbs'), packs:sum('packs'),
            clips:sum('clips'), watts, amps:watts/120,
            circuits: Math.max(watts ? Math.ceil(watts/cap) : 0, per.filter(p=>p.watts).length ? 1 : 0)};
  }

  /* ---------- Render ---------- */
  function hint(msg){ $('#hint').innerHTML = msg; }

  function renderStrings(t){
    const ul = $('#stringList'); ul.innerHTML = '';
    t.per.forEach(p => {
      const s = p.s, li = document.createElement('li');
      li.className = 'rg-str' + (s.id === S.active ? ' rg-active' : '');
      li.style.setProperty('--sw', s.color);
      li.innerHTML = `<div class="rg-row">
          <span class="rg-sw" aria-hidden="true"></span>
          <input type="text" value="${esc(s.name)}" aria-label="String name">
          <span class="rg-len">${fmt(p.feet)}</span>
          ${s.id === S.active ? '<span class="rg-tag">Selected</span>' : ''}
          ${S.strings.length > 1 ? '<button type="button" class="rg-ghost rg-rm">Remove</button>' : ''}
        </div><ul class="rg-runs"></ul>`;
      li.onclick = e => { if (!e.target.closest('input,button')) selectString(s.id); };
      const inp = li.querySelector('input');
      inp.onfocus = () => selectString(s.id);
      inp.oninput = () => { s.name = inp.value; renderResults(totals()); $('#addTo').textContent = `Adds to: ${s.name}`; };
      const rm = li.querySelector('.rg-rm'); if (rm) rm.onclick = () => removeString(s.id);

      const runs = li.querySelector('.rg-runs');
      const items = itemsFor(s.id);
      if (!items.length) runs.innerHTML = `<li class="rg-empty-row">${s.id===S.active ? 'Trace on the photo or add a run by hand.' : 'No runs yet. Select this string to add some.'}</li>`;
      let tracedN = 0;
      items.forEach(it => {
        const r = document.createElement('li');
        const name = it.kind === 'photo' ? `Traced run ${++tracedN}` : it.label;
        r.innerHTML = `<span></span><span class="rg-len">${it.feet == null ? 'set scale' : fmt(it.feet)}</span>`;
        r.firstChild.textContent = name;
        if (it.kind !== 'live'){
          const b = document.createElement('button'); b.className = 'rg-ghost'; b.type = 'button'; b.textContent = 'Remove';
          b.setAttribute('aria-label', `Remove ${name}`);
          b.onclick = ev => { ev.stopPropagation(); (it.kind === 'photo' ? S.runs : S.manual).splice(it.idx,1); update(); };
          r.appendChild(b);
        }
        runs.appendChild(r);
      });
      ul.appendChild(li);
    });
  }

  function renderResults(t){
    const runCount = S.runs.length + (S.current.length>=2?1:0) + S.manual.length;
    $('#rTotal').textContent = fmt(t.total);
    $('#rSub').textContent = `of roofline across ${runCount} run${runCount===1?'':'s'} on ${S.strings.length} string${S.strings.length===1?'':'s'}`;
    $('#rBuy').textContent = `${Math.ceil(t.buy)} ft`;
    $('#rBulbs').textContent = t.bulbs.toLocaleString();
    $('#rPackLabel').textContent = `${num('#pack')} ft lengths`;
    $('#rPacks').textContent = t.packs;
    $('#rClips').textContent = t.clips.toLocaleString();
    $('#rWatts').textContent = `${Math.round(t.watts).toLocaleString()} W`;
    $('#rCircuits').textContent = t.circuits;

    const br = $('#rBreak');
    br.hidden = S.strings.length < 2;
    br.innerHTML = '';
    t.per.forEach(p => {
      const li = document.createElement('li');
      li.style.setProperty('--sw', p.s.color);
      li.innerHTML = `<span class="rg-sw"></span><span></span><span class="rg-v">${fmt(p.feet)}, ${p.packs} × ${num('#pack')} ft, ${Math.round(p.watts)} W</span>`;
      li.children[1].textContent = p.s.name;
      br.appendChild(li);
    });

    const over = t.per.filter(p => p.circuits > 1);
    const w = $('#rWarn');
    if (over.length){
      w.hidden = false;
      w.textContent = `${over.map(p=>p.s.name).join(' and ')} ${over.length>1?'draw':'draws'} more than one ${num('#amps')} amp circuit can safely carry (${Math.round(t.cap)} W at 80%). Split ${over.length>1?'them':'it'} into more strings on separate circuits.`;
    } else if (t.circuits > 1){
      w.hidden = false;
      w.textContent = `About ${t.amps.toFixed(1)} amps in total. Plug the strings into outlets on at least ${t.circuits} different circuits.`;
    } else w.hidden = true;
  }

  function update(){
    const has = !!S.img, cal = !!S.pxPerFt;
    $('#mScale').disabled = !has; $('#mTrace').disabled = !has;
    $('#finish').disabled = S.current.length < 2;
    $('#undo').disabled = !(S.current.length || S.runs.length || S.scalePts.length);
    $('#clear').disabled = !(S.current.length || S.runs.length);
    $('#preview').disabled = !(has && (S.runs.length || S.current.length >= 2));
    $('#reset').disabled = !(has || S.runs.length || S.current.length || S.manual.length || S.strings.length > 1);
    $('#savePhoto').disabled = !(cal && (S.runs.length || S.current.length >= 2));

    const step = !has ? 1 : !cal ? 2 : 3;
    root.querySelectorAll('#rg-steps li').forEach(li => {
      const n = +li.dataset.s;
      li.classList.toggle('rg-on', n === step);
      li.classList.toggle('rg-done', n < step);
    });

    const sName = esc(strOf(S.active).name);
    if (!has){ if (!$('#hint').textContent.startsWith('Saved')) hint('Upload a photo to start, or add runs by hand on the right.'); }
    else if (S.mode === 'scale'){
      hint(S.scalePts.length < 2
        ? '<strong>Set the scale:</strong> click both ends of something you know the length of, like the width of the garage door.'
        : '<strong>Enter the real length</strong> of the red line below.');
    } else if (coarse){
      hint(S.current.length
        ? `<strong>Tracing ${sName}:</strong> tap each corner, then tap Finish run at the end.`
        : `<strong>Tracing ${sName}:</strong> tap where the lights start.${cal ? '' : ' Set the scale to see lengths.'}`);
    } else {
      hint(S.current.length
        ? `<strong>Tracing ${sName}:</strong> keep clicking along the roof edge. Click the last point again, press Enter, or click Finish run to end this run.`
        : `<strong>Tracing ${sName}:</strong> click where the lights start, then each corner and peak.${cal ? '' : ' Set the scale to see lengths.'}`);
    }
    $('#addTo').textContent = `Adds to: ${strOf(S.active).name}`;

    const t = totals();
    renderStrings(t);
    renderResults(t);
    draw();
    schedulePreview();
  }

  $('#copy').onclick = async () => {
    const t = totals();
    const lines = [
      'Roofline lighting estimate',
      `Measured: ${fmt(t.total)}`,
      `Lights to buy (with ${num('#waste')}% extra): ${Math.ceil(t.buy)} ft`,
      `${num('#pack')} ft lengths: ${t.packs}`,
      `Bulbs at ${num('#spacing')} in spacing: ${t.bulbs}`,
      `Clips: ${t.clips}`,
      `Power: ${Math.round(t.watts)} W (${t.amps.toFixed(1)} A), ${t.circuits} circuit(s)`
    ];
    t.per.forEach(p => {
      lines.push('', `${p.s.name}: ${fmt(p.feet)}, ${p.packs} × ${num('#pack')} ft, ${p.bulbs} bulbs, ${Math.round(p.watts)} W`);
      let n = 0;
      itemsFor(p.s.id).forEach(it => lines.push(`  ${it.kind==='photo' ? `Traced run ${++n}` : it.label}: ${it.feet==null ? 'not scaled' : fmt(it.feet)}`));
    });
    try { await navigator.clipboard.writeText(lines.join('\n')); $('#copy').textContent = 'Copied'; }
    catch { $('#copy').textContent = 'Copy failed. Select and copy manually.'; }
    setTimeout(() => $('#copy').textContent = 'Copy summary', 1800);
  };

  update();
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
